items.example:
.box {
  width: 100px;
  height: 100px;
  padding: 10px;
}

.content { box-sizing: content-box; }
.border { box-sizing: border-box; }

content.code:
.container {
  justify-content:
    flex-start | flex-end | center |
    space-between | space-around |
    space-evenly | start | end | left;
}

.container {
  align-items: stretch | flex-start |
   flex-end | center |
   baseline;
}

.container {
  align-content: flex-start | flex-end |
center | space-between |
space-around |
space-evenly | stretch |
start | end | baseline;
}

.item {
  /* sarà minimo 200px, ma crescerà se ne avrà la possibilità */
  flex: 1 0 200px;
  /* sarà 200px al massimo e potrà contrarsi se necessario */
  flex: 0 1 200px;
  /* assumerà la dimensione dei contenuti e potrà crescere se avrà spazio */
  flex: 1 0 auto;
  /*default*/
  flex: 0 1 auto;
}

.item {
  align-self: auto | flex-start | flex-end | center | baseline | stretch;
}
